#ifndef CLOUDBERRY_SDK_STREAM_H
#define CLOUDBERRY_SDK_STREAM_H
#include "service.h"
#include "../interfaces/stream.h"
#include "../interfaces/filesystem.h"
static inline cb_status_t cb_stream_read(struct cb_client *c,cb_handle_t h,void *out,size_t capacity,size_t *actual,unsigned flags){struct cb_stream_read r={capacity>CB_STREAM_CHUNK?CB_STREAM_CHUNK:capacity,flags};cb_status_t status=cb_invoke(c,h,(struct cb_interface_id)CB_STREAM_INTERFACE_ID,CB_STREAM_READ,&r,sizeof(r),0);if(!status){struct cb_reply_header reply;cb_copy(&reply,c->result,sizeof(reply));if(reply.result_bytes>r.bytes)return CB_BAD_REQUEST;cb_copy(out,cb_result(c),reply.result_bytes);*actual=reply.result_bytes;}return status;}
static inline cb_status_t cb_stream_write(struct cb_client *c,cb_handle_t h,const void *data,size_t bytes,size_t *actual,unsigned flags){unsigned char buffer[8+CB_STREAM_CHUNK];struct cb_stream_write w={flags};size_t count=bytes>CB_STREAM_CHUNK?CB_STREAM_CHUNK:bytes;cb_copy(buffer,&w,8);cb_copy(buffer+8,data,count);cb_status_t status=cb_invoke(c,h,(struct cb_interface_id)CB_STREAM_INTERFACE_ID,CB_STREAM_WRITE,buffer,8+count,0);if(!status){uint64_t n;cb_copy(&n,cb_result(c),8);if(n>count)return CB_BAD_REQUEST;*actual=n;}return status;}
static inline cb_status_t cb_write_all(struct cb_client *c,cb_handle_t h,const void *data,size_t bytes){size_t offset=0;while(offset<bytes){size_t n=0;cb_status_t status=cb_stream_write(c,h,(const unsigned char *)data+offset,bytes-offset,&n,0);if(status)return status;if(!n)return CB_RESOURCE_FAILURE;offset+=n;}return CB_OK;}
static inline cb_status_t cb_fs_call(struct cb_client *c,cb_handle_t filesystem,unsigned op,const char *path,unsigned mode,uint64_t cursor){size_t n=cb_length(path);if(n>4095)return CB_BAD_REQUEST;unsigned char frame[sizeof(struct cb_filesystem_request)+4095];struct cb_filesystem_request request={mode,n,cursor};cb_copy(frame,&request,sizeof(request));cb_copy(frame+sizeof(request),path,n);return cb_invoke(c,filesystem,(struct cb_interface_id)CB_FILESYSTEM_INTERFACE_ID,op,frame,sizeof(request)+n,0);}
static inline cb_status_t cb_fs_chown(struct cb_client *c,cb_handle_t filesystem,const char *path,uint64_t uid,uint64_t gid){size_t n=cb_length(path);if(n>4095)return CB_BAD_REQUEST;unsigned char frame[sizeof(struct cb_filesystem_request)+4095+sizeof(struct cb_filesystem_owner)];struct cb_filesystem_request request={.path_bytes=n};struct cb_filesystem_owner owner={uid,gid};cb_copy(frame,&request,sizeof(request));cb_copy(frame+sizeof(request),path,n);cb_copy(frame+sizeof(request)+n,&owner,sizeof(owner));return cb_invoke(c,filesystem,(struct cb_interface_id)CB_FILESYSTEM_INTERFACE_ID,CB_FILESYSTEM_CHOWN,frame,sizeof(request)+n+sizeof(owner),0);}
/* Lexical canonicalization only; filesystem policy remains authoritative. */
static inline int cb_path(char *out,size_t capacity,const char *cwd,const char *name){size_t at=0;const char *parts[2]={name[0]=='/'?"":cwd,name};if(capacity<2)return 0;out[at++]='/';for(unsigned part=0;part<2;++part){const char *s=parts[part];while(*s){while(*s=='/')++s;const char *start=s;while(*s && *s!='/')++s;size_t n=s-start;if(!n || (n==1 && start[0]=='.'))continue;if(n==2 && start[0]=='.' && start[1]=='.'){if(at>1){while(at>1 && out[at-1]!='/')--at;if(at>1)--at;}continue;}if(at>1){if(at+1>=capacity)return 0;out[at++]='/';}if(n>=capacity-at)return 0;cb_copy(out+at,start,n);at+=n;}}out[at]=0;return 1;}
#endif
